                        "For example, respond with: "
                        '{"index.js": {"content": "code here"}, "App.css": {"content": "code here"}, "package.json": {"content": "code here"}}'
                    )
                },
                {"role": "user", "content": prompt}
            ],

                functions=[
                    {
                        "name": "generate_code_files",
